### src/tools/query-hyperindex.ts

Create a tool that queries the Hyperindex GraphQL API to search/browse occurrences and hypercerts.

```typescript
export type QueryType = 'occurrences' | 'hypercerts' | 'search';

export interface QueryInput {
  type: QueryType;
  // For occurrences/hypercerts: filter by DID
  did?: string;
  // For search: free-text query
  searchQuery?: string;
  // Pagination
  limit?: number;  // default 10, max 20
}

export interface QueryResult {
  success: true;
  type: QueryType;
  totalCount: number;
  records: Array<{
    uri: string;
    // Occurrence fields
    scientificName?: string;
    vernacularName?: string;
    eventDate?: string;
    country?: string;
    locality?: string;
    // Hypercert fields
    title?: string;
    shortDescription?: string;
    // Common
    did: string;
    createdAt?: string;
    hyperscanUrl: string;
  }>;
}

export interface QueryError {
  success: false;
  error: string;
}

export type QueryResponse = QueryResult | QueryError;

export async function queryHyperindex(input: QueryInput): Promise<QueryResponse>
```

Implementation:
1. POST to `https://api.hi.gainforest.app/graphql` using native fetch
2. Build GraphQL query based on type:

For `occurrences`:
```graphql
query {
  appGainforestDwcOccurrence(first: $limit, where: { did: { eq: "$did" } }) {
    edges { node { uri did scientificName vernacularName eventDate country locality createdAt } }
    totalCount
  }
}
```
(omit `where` clause if no did filter)

For `hypercerts`:
```graphql
query {
  orgHypercertsClaimActivity(first: $limit, where: { did: { eq: "$did" } }) {
    edges { node { uri did title shortDescription createdAt } }
    totalCount
  }
}
```

For `search`:
```graphql
query {
  search(query: "$searchQuery", first: $limit) {
    edges { node { uri did collection } }
    totalCount
  }
}
```

3. Build hyperscanUrl for each record from the URI components
4. Timeout: 15 seconds (AbortController)
5. Return error if fetch fails (fail-soft)

