  // Who submitted this
  submittedBy: TelegramUser;
}

export interface HypercertResult {
  success: true;
  uri: string;
  cid: string;
  title: string;
  hyperscanUrl: string;  // Link to view on Hyperscan
}

export interface HypercertError {
  success: false;
  error: string;
}

export type HypercertResponse = HypercertResult | HypercertError;

export async function createHypercert(input: HypercertInput): Promise<HypercertResponse>
```

Implementation:
1. Validate title and shortDescription are non-empty
2. Get ATProto agent via `getAtprotoAgent(config)` and community DID
3. If image provided, upload blob (same pattern as publish-occurrence.ts)
4. Optionally create a location record (`app.certified.location`) if lat/lng provided:
   ```typescript
   const locationResult = await agent.com.atproto.repo.createRecord({
     repo: did,
     collection: 'app.certified.location',
     record: {
       $type: 'app.certified.location',
       locationType: 'coordinate-decimal',
       location: { string: `${lat},${lng}` },
       name: locationName || 'Observation site',
       createdAt: new Date().toISOString(),
     },
   });
   ```
5. Build the hypercert record:
   ```typescript
   const record = {
     $type: 'org.hypercerts.claim.activity',
     title: input.title,
     shortDescription: input.shortDescription,
     createdAt: new Date().toISOString(),
     // Optional fields
     ...(input.description && { description: input.description }),
     ...(input.startDate && { startDate: input.startDate }),
     ...(input.endDate && { endDate: input.endDate }),
     ...(input.workScope && { workScope: input.workScope }),
     ...(imageBlob && { image: { $type: 'blob', ref: imageBlob.ref, mimeType: imageBlob.mimeType, size: imageBlob.size } }),
     ...(locationRef && { locations: [{ uri: locationRef.uri, cid: locationRef.cid }] }),
   };
   ```
6. Create the record in collection `org.hypercerts.claim.activity`
7. Build hyperscanUrl: `https://www.hyperscan.dev/data?did=${encodeURIComponent(did)}&collection=org.hypercerts.claim.activity&rkey=${rkey}`
   (extract rkey from the URI: `uri.split('/').pop()`)
8. Return success with uri, cid, title, hyperscanUrl

